r_rows = data_rows('Rules', {'B': 'string', 'C': 'string', 'D': 'number'})
r_data = [cells('Rules', f'B{i}:D{i}')[0] for i in r_rows]

# Build adjacency: parent -> list of (component, count)
rules = {}
for p, c, n in r_data:
    rules.setdefault(p, []).append((c, n))

def expand(part):
    if part not in rules:
        return {part: 1}
    res = {}
    for comp, count in rules[part]:
        sub = expand(comp)
        for k, v in sub.items():
            res[k] = res.get(k, 0) + v * count
    return res

beacon_counts = expand('Beacon')
result = [beacon_counts.get('Alloy', 0), beacon_counts.get('Bolt', 0), beacon_counts.get('Wire', 0)]

